<?php
require_once __DIR__.'/../includes/admin_ui.php';
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM subjects WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??'');$id=(int)($_POST['id']??0);$d=[trim($_POST['name']),trim($_POST['code']),$_POST['status']];if($id){$pdo->prepare("UPDATE subjects SET name=?,code=?,status=? WHERE id=?")->execute([...$d,$id]);audit($pdo,'update','Updated subject #'.$id);go('subjects.php','Subject updated successfully');}$pdo->prepare("INSERT INTO subjects(name,code,status) VALUES(?,?,?)")->execute($d);audit($pdo,'create','Created subject');go('subjects.php','Subject added successfully');}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$pdo->prepare("UPDATE subjects SET status='Inactive' WHERE id=?")->execute([$id]);audit($pdo,'delete','Deactivated subject #'.$id);go('subjects.php','Subject deactivated');}
$rows=$pdo->query("SELECT * FROM subjects ORDER BY name")->fetchAll();
admin_layout('Subjects','Create, edit and deactivate subjects used across the academic system.');echo '<div class="actions"><button class="btn" data-modal="subjectModal">＋ Add Subject</button></div></div>';flash();
echo '<div class="card"><div class="toolbar"><input class="search" data-search="#subjectTable" placeholder="Search subject or code"><span class="muted">'.count($rows).' records</span></div><div class="table-wrap"><table class="table" id="subjectTable"><thead><tr><th>Subject</th><th>Code</th><th>Status</th><th>Actions</th></tr></thead><tbody>';
foreach($rows as $r){echo '<tr><td><b>'.e($r['name']).'</b></td><td>'.e($r['code']??'').'</td><td><span class="badge '.($r['status']==='Active'?'success':'danger').'">'.e($r['status']).'</span></td><td class="actions-cell"><a class="btn light small" href="?edit='.$r['id'].'">Edit</a><a class="btn danger small" data-confirm="Deactivate this subject?" href="?delete='.$r['id'].'">Deactivate</a></td></tr>';}
echo '</tbody></table></div></div><div class="modal" id="subjectModal"><div class="modal-box"><div class="modal-head"><h2>'.($edit?'Edit Subject':'Add Subject').'</h2><button class="close">×</button></div><form class="form" method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="id" value="'.e((string)($edit['id']??0)).'"><div class="form-grid"><label>Subject Name<input name="name" required value="'.e($edit['name']??'').'"></label><label>Code<input name="code" value="'.e($edit['code']??'').'"></label><label>Status<select name="status"><option>Active</option><option'.(($edit['status']??'')==='Inactive'?' selected':'').'>Inactive</option></select></label></div><div class="form-actions"><button type="button" class="btn light close">Cancel</button><button class="btn">'.($edit?'Update Subject':'Save Subject').'</button></div></form></div></div>';if($edit)echo '<script>document.getElementById("subjectModal").classList.add("show")</script>';admin_end();